/* global console, process */

import { createHash } from "node:crypto";
import { mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const vendorRoot = path.dirname(fileURLToPath(import.meta.url));
const packageRoot = path.resolve(vendorRoot, "../..");
const upstreamRoot = path.join(vendorRoot, "upstream");
const coreRoot = path.join(upstreamRoot, "core");
const runtimeRoot = path.join(packageRoot, "src/vendor/msdfgen");
const buildRoot = mkdtempSync(path.join(tmpdir(), "genome-spy-msdfgen-"));
const wasmPath = path.join(buildRoot, "msdfgen.wasm");
const coreSources = [
    "Contour.cpp",
    "DistanceMapping.cpp",
    "EdgeHolder.cpp",
    "MSDFErrorCorrection.cpp",
    "Projection.cpp",
    "Scanline.cpp",
    "Shape.cpp",
    "contour-combiners.cpp",
    "convergent-curve-ordering.cpp",
    "edge-coloring.cpp",
    "edge-segments.cpp",
    "edge-selectors.cpp",
    "equation-solver.cpp",
    "msdf-error-correction.cpp",
    "msdfgen.cpp",
];
const sources = coreSources.map((name) => path.join(coreRoot, name));

const exportedFunctions = [
    "_free",
    "_malloc",
    "_msdf_abi_version",
    "_msdf_render_v1",
];
const args = [
    "-std=c++11",
    "-Oz",
    "-flto",
    "-fno-exceptions",
    "-fno-rtti",
    "-DMSDFGEN_USE_CPP11",
    "-DMSDFGEN_PUBLIC=",
    "--no-entry",
    "-sSTANDALONE_WASM=1",
    "-sALLOW_MEMORY_GROWTH=1",
    "-sMALLOC=emmalloc",
    "-sFILESYSTEM=0",
    `-sEXPORTED_FUNCTIONS=${JSON.stringify(exportedFunctions)}`,
    "-I",
    upstreamRoot,
    path.join(vendorRoot, "wrapper.cpp"),
    ...sources,
    "-o",
    wasmPath,
];
const result = spawnSync("em++", args, {
    encoding: "utf8",
    env: process.env,
});
if (result.status !== 0) {
    process.stderr.write(result.stdout);
    process.stderr.write(result.stderr);
    throw new Error("Failed to build msdfgen WASM.");
}

const wasm = readFileSync(wasmPath);
const sha256 = createHash("sha256").update(wasm).digest("hex");
const generated =
    `// Generated by vendor/msdfgen/build.mjs. Do not edit.\n` +
    `export const MSDFGEN_WASM_BASE64 = ${JSON.stringify(wasm.toString("base64"))};\n` +
    `export const MSDFGEN_WASM_SHA256 = ${JSON.stringify(sha256)};\n`;
writeFileSync(path.join(runtimeRoot, "wasmBinary.js"), generated);
console.log(`Generated ${wasm.length} byte msdfgen WASM (${sha256}).`);
